#!/usr/bin/env python3
"""
Round 179b (culprits-tiles-more), 5 October 2026.

NASA Earthdata helper, salt marsh loss and burned area scripts. Whole files,
each written only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {
    "scripts/lib/earthdata.py": "",
    "scripts/salt_marsh.py": "",
    "scripts/burned_area.py": "",
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"round179b_tiles: {name} already up to date")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"round179b_tiles: wrote {name}")


if __name__ == "__main__":
    main()
